#include <signal.h>
#include <unistd.h>

volatile sig_atomic_t recus = 0;

void compter(int sig) {
    (void) sig;
    recus = recus + 1;
}

int main(void) {
    sigset_t bloc;
    sigemptyset(&bloc);
    sigaddset(&bloc, SIGUSR1);

    signal(SIGUSR1, compter);
    sigprocmask(SIG_BLOCK, &bloc, NULL);

    raise(SIGUSR1);
    raise(SIGUSR1);
    raise(SIGUSR1);

    sigprocmask(SIG_UNBLOCK, &bloc, NULL);

    printf("recus = %d\n", (int) recus);
    return 0;
}

